 String? // SHREE SONY NX\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  items Item[]\n\n  @@map(\"products\")\n}\n\n// ─────────────────────────────────────────\n// ITEM (Individual stock entry with IMEI etc.)\n// ─────────────────────────────────────────\nmodel Item {\n  id         Int       @id @default(autoincrement())\n  itemId     String    @unique // ITM-4029\n  productId  Int\n  product    Product   @relation(fields: [productId], references: [id])\n  supplierId Int?\n  supplier   Supplier? @relation(fields: [supplierId], references: [id])\n  model      String? // Eco Volt Neo, 512GB\n  brand      String? // Samsung, Luminous\n  colour     String? // Phantom Black\n  imeiNo     String?   @unique\n  dp         Float? // Dealer Price\n  salePrice  Float?\n  tax        String? // Standard (20%)\n  quantity   Int       @default(0)\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  // Relations\n  priceHistory PriceHistory[]\n\n  @@map(\"items\")\n}\n\n// ─────────────────────────────────────────\n// PRICE HISTORY (for Price Drop / Change Master)\n// ─────────────────────────────────────────\nmodel PriceHistory {\n  id           Int      @id @default(autoincrement())\n  itemId       Int\n  item         Item     @relation(fields: [itemId], references: [id])\n  oldDp        Float?\n  newDp        Float?\n  oldSalePrice Float?\n  newSalePrice Float?\n  oldImei      String?\n  newImei      String?\n  remark       String?\n  changedAt    DateTime @default(now())\n\n  @@map(\"price_history\")\n}\n\n// ─────────────────────────────────────────\n// DOA RECORD\n// ─────────────────────────────────────────\nmodel DOARecord {\n  id          Int      @id @default(autoincrement())\n  supplierId  Int\n  supplier    Supplier @relation(fields: [supplierId], references: [id])\n  invoiceNo   String\n  invoiceDate DateTime\n  totalQty    Int\n  totalAmount Float\n  itemId      String?\n  productName String?\n  createdAt   DateTime @default(now())\n\n  @@map(\"doa_records\")\n}\n\n// ─────────────────────────────────────────\n// SALES PERSON\n// ─────────────────────────────────────────\nmodel SalesPerson {\n  id         Int      @id @default(autoincrement())\n  employeeId String   @unique // EMP-1042\n  name       String\n  mobile     String?\n  contactNo  String?\n  email      String?\n  address    String?\n  visible    Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  sales Sale[]\n\n  @@map(\"sales_persons\")\n}\n\n// ─────────────────────────────────────────\n// SERVICE CENTER\n// ─────────────────────────────────────────\nmodel ServiceCenter {\n  id              Int      @id @default(autoincrement())\n  serialNo        String   @unique\n  productType     String?\n  brandName       String?\n  serviceCentreNo String?\n  createdAt       DateTime @default(now())\n\n  @@map(\"service_centers\")\n}\n\n// ─────────────────────────────────────────\n// SALE (for Report)\n// ─────────────────────────────────────────\nmodel Sale {\n  id            Int          @id @default(autoincrement())\n  invoiceNo     String       @unique\n  invoiceDate   DateTime\n  customerId    Int?\n  customer      Customer?    @relation(fields: [customerId], references: [id])\n  salesPersonId Int?\n  salesPerson   SalesPerson? @relation(fields: [salesPersonId], references: [id])\n  itemId        String?\n  productName   String?\n  model         String?\n  brand         String?\n  quantity      Int\n  amount        Float\n  createdAt     DateTime     @default(now())\n\n  @@map(\"sales\")\n}\n\n// ─────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────\nenum ProductType {\n  SINGLE\n  MULTIPLE\n}\n",
